import{_ as e,o as i,c as a,a2 as t}from"./chunks/framework.Cv-B11KK.js";const k=JSON.parse('{"title":"Clean install walkthrough","description":"","frontmatter":{},"headers":[],"relativePath":"install.md","filePath":"install.md","lastUpdated":1790343991000}'),n={name:"install.md"};function l(o,s,r,p,h,d){return i(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="clean-install-walkthrough" tabindex="-1">Clean install walkthrough <a class="header-anchor" href="#clean-install-walkthrough" aria-label="Permalink to &quot;Clean install walkthrough&quot;">​</a></h1><p>This takes a Mac with nothing LaTeX-related on it to a working bbtex: a compiled PDF, SyncTeX in both directions and an equation preview. It&#39;s also the check I want every release to pass on a fresh macOS account before I call it done. It takes about half an hour, most of it waiting for MacTeX to download.</p><p class="meta"><strong>You need:</strong> an Apple Silicon Mac, an admin password for the installers, and about 6 GB of free disk space for MacTeX.</p><h2 id="install-the-tools" tabindex="-1">Install the tools <a class="header-anchor" href="#install-the-tools" aria-label="Permalink to &quot;Install the tools&quot;">​</a></h2><ol><li><p><strong>BBEdit.</strong> Download it from <a href="https://www.barebones.com/products/bbedit/" target="_blank" rel="noreferrer">barebones.com</a> and move it to <code>/Applications</code>. The free mode is enough.</p></li><li><p><strong>MacTeX.</strong> Download <code>MacTeX.pkg</code> from <a href="https://tug.org/mactex/" target="_blank" rel="noreferrer">tug.org/mactex</a> and run the installer. It provides pdfLaTeX, XeLaTeX, LuaLaTeX, latexmk, BibTeX, Biber and <code>preview.sty</code>. Open a <strong>new</strong> Terminal window afterwards and check:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">latexmk</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> head</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">biber</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --version</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 2.21 or later</span></span></code></pre></div></li><li><p><strong>Skim.</strong> Download it from <a href="https://skim-app.sourceforge.io/" target="_blank" rel="noreferrer">skim-app.sourceforge.io</a> and move it to <code>/Applications</code>.</p></li><li><p><strong>Optional, for equation previews and completion:</strong> with <a href="https://brew.sh" target="_blank" rel="noreferrer">Homebrew</a> installed,</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">brew</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> poppler</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> texlab</span></span></code></pre></div><p><code>poppler</code> provides <code>pdftoppm</code>, which turns previews into images. <code>texlab</code> gives BBEdit LaTeX completion and Go to Definition.</p></li></ol><h2 id="install-bbtex" tabindex="-1">Install bbtex <a class="header-anchor" href="#install-bbtex" aria-label="Permalink to &quot;Install bbtex&quot;">​</a></h2><ol><li><p>Download <code>bbtex-macos-arm64.bbpackage.zip</code> from the <a href="https://github.com/LouLouLibs/bbtex/releases/latest" target="_blank" rel="noreferrer">latest release</a> and double-click it to unzip. If you want to check the download, compare <code>shasum -a 256 bbtex-macos-arm64.bbpackage.zip</code> with <code>SHA256SUMS-arm64.txt</code> from the same release.</p></li><li><p>Move <code>bbtex.bbpackage</code> into BBEdit&#39;s packages folder:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Application</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Support/BBEdit/Packages</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Downloads/bbtex.bbpackage</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Application</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Support/BBEdit/Packages/</span></span></code></pre></div></li><li><p><strong>Clear the download quarantine.</strong> bbtex isn&#39;t signed with an Apple Developer ID yet, so macOS blocks a copy downloaded with a web browser and shows <em>&quot;Apple could not verify “bbtex” is free of malware…&quot;</em>. With BBEdit quit, run:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">xattr</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -dr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.apple.quarantine</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Application</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Support/BBEdit/Packages/bbtex.bbpackage</span></span></code></pre></div><p>Only do this for a package you downloaded from the release page above.</p></li><li><p>Open BBEdit. The <strong>Scripts</strong> menu now has a set of <strong>LaTeX —</strong> commands and a <strong>LaTeX Editing</strong> submenu.</p></li><li><p>Run <strong>Scripts → LaTeX — Doctor</strong>. It checks the TeX tools, Skim, the package and BBEdit&#39;s setup, without changing anything. Items marked <code>OPTIONAL</code> are fine to skip; fix anything marked <code>WARN</code>. If it prints a <code>[bbtex]</code> quarantine message instead, repeat step 3.</p></li></ol><h2 id="set-up-bbedit-and-skim" tabindex="-1">Set up BBEdit and Skim <a class="header-anchor" href="#set-up-bbedit-and-skim" aria-label="Permalink to &quot;Set up BBEdit and Skim&quot;">​</a></h2><ol><li><p><strong>Shortcuts.</strong> In <strong>BBEdit → Settings → Menus &amp; Shortcuts</strong>, scroll to <strong>Scripts</strong> and assign:</p><table tabindex="0"><thead><tr><th>Script</th><th>Shortcut</th></tr></thead><tbody><tr><td>LaTeX — Compile</td><td><kbd>⌘K</kbd></td></tr><tr><td>LaTeX — Forward Search</td><td><kbd>⇧⌘J</kbd></td></tr><tr><td>LaTeX — Compile With…</td><td><kbd>⇧⌘K</kbd></td></tr></tbody></table><p>Remove any existing command that already uses one of those keys.</p></li><li><p><strong>Inverse search.</strong> In <strong>Skim → Settings → Sync</strong>, choose the <em>Custom</em> preset, command <code>/usr/local/bin/bbedit</code>, arguments <code>--line %line &quot;%file&quot;</code>. If <code>/usr/local/bin/bbedit</code> doesn&#39;t exist, install BBEdit&#39;s command-line tools from <strong>BBEdit → Install Command Line Tools…</strong>.</p></li><li><p><strong>TexLab (optional).</strong> If you installed <code>texlab</code>, open <strong>BBEdit → Settings → Languages</strong>, select <strong>TeX</strong>, and check that the language server is enabled and finds <code>texlab</code>.</p></li></ol><h2 id="first-build" tabindex="-1">First build <a class="header-anchor" href="#first-build" aria-label="Permalink to &quot;First build&quot;">​</a></h2><ol><li><p>Make a test folder with one file, <code>test.tex</code>:</p><div class="language-latex vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">latex</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\\documentclass</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">article</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\\usepackage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">amsmath</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\begin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{document}</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\section</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Hello</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\\label</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">sec:hello</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Energy is</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\begin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{equation}</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\\label</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">eq:energy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  E = mc^2</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\end</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{equation}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">See Section~</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">\\ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">sec:hello</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}.</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\end</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{document}</span></span></code></pre></div></li><li><p>Open it in BBEdit and press <kbd>⌘K</kbd>. The first time, macOS may ask whether BBEdit may control Skim; allow it. Skim opens the PDF at the cursor without taking focus, and a notification reports the build.</p></li><li><p><strong>Errors.</strong> Change <code>\\section</code> to <code>\\sectoin</code> and press <kbd>⌘K</kbd>. <strong>LaTeX Results</strong> opens with an error on line 4; click it to jump there. Fix it and build again: the error is gone.</p></li><li><p><strong>SyncTeX.</strong> Put the cursor on the equation and press <kbd>⇧⌘J</kbd>; Skim highlights it. ⌘-click a word in Skim to jump back to BBEdit.</p></li><li><p><strong>Preview (needs Poppler).</strong> Select <code>E = mc^2</code> and run <strong>Scripts → LaTeX — Preview Selection</strong>. A small window shows the rendered equation, and your selection stays in place.</p></li><li><p><strong>Outline.</strong> Run <strong>Scripts → LaTeX — Project Outline Window</strong>, search for <code>energy</code>, and press Return to jump to the equation.</p></li></ol><p>If each step works, the install is good.</p><h2 id="optional-extras" tabindex="-1">Optional extras <a class="header-anchor" href="#optional-extras" aria-label="Permalink to &quot;Optional extras&quot;">​</a></h2><ul><li><p><strong>Preview on save.</strong> Install the save attachment, then turn it on per file with <strong>LaTeX — Toggle Preview on Save</strong>:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Library/Application Support/BBEdit/Packages/bbtex.bbpackage/Contents/Resources/install-preview-save-hook.sh&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --apply</span></span></code></pre></div><p>It refuses to replace another tool&#39;s save attachment.</p></li><li><p><strong>Right-click preview.</strong> Add <strong>LaTeX — Preview Selection</strong> to BBEdit&#39;s Services menu:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$HOME</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/Library/Application Support/BBEdit/Packages/bbtex.bbpackage/Contents/Resources/bbtex&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> preview-service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div></li><li><p><strong>Live selection preview</strong> needs nothing extra: run <strong>LaTeX — Toggle Live Selection Preview</strong>.</p></li></ul><p>See <a href="./selection-preview">equation previews</a> for details.</p><h2 id="upgrade-or-roll-back" tabindex="-1">Upgrade or roll back <a class="header-anchor" href="#upgrade-or-roll-back" aria-label="Permalink to &quot;Upgrade or roll back&quot;">​</a></h2><ol><li>Quit BBEdit.</li><li>Move the installed <code>bbtex.bbpackage</code> somewhere safe (it&#39;s your rollback copy).</li><li>Install the new release as above, including the quarantine step.</li><li>Open BBEdit and run <strong>LaTeX — Doctor</strong> and one build.</li></ol><p>To roll back, quit BBEdit, put the old package back in <code>Packages</code>, and reopen BBEdit.</p><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><ol><li><p>Turn off <strong>Preview on Save</strong> and <strong>Live Selection Preview</strong> if you use them, close any bbtex preview windows, and quit BBEdit.</p></li><li><p>Remove the package:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -rf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/Library/Application</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">Support/BBEdit/Packages/bbtex.bbpackage</span></span></code></pre></div></li><li><p>If you installed the save attachment, remove <code>~/Library/Application Support/BBEdit/Attachment Scripts/Document.documentDidSave.scpt</code> and <code>Document.documentDidSave.scpt.bbtex-receipt</code>, but only if Doctor still identifies it as bbtex&#39;s unchanged hook. If another tool shares it, leave it for manual review.</p></li><li><p>If you installed the right-click service, remove <code>~/Library/Services/LaTeX — Preview Selection.workflow</code>.</p></li><li><p>Optionally delete bbtex&#39;s cache and state, <code>~/.local/state/bbtex</code>.</p></li></ol><p>Your documents, PDFs and TeX installation are never touched.</p><h2 id="if-something-goes-wrong" tabindex="-1">If something goes wrong <a class="header-anchor" href="#if-something-goes-wrong" aria-label="Permalink to &quot;If something goes wrong&quot;">​</a></h2><p>Start with <a href="./setup-troubleshooting">troubleshooting</a>. If a step here doesn&#39;t match what you see, that&#39;s a bug in these instructions: <a href="https://github.com/LouLouLibs/bbtex/issues" target="_blank" rel="noreferrer">open an issue</a> and include the Doctor report, plus your macOS, BBEdit and MacTeX versions.</p>`,23)])])}const g=e(n,[["render",l]]);export{k as __pageData,g as default};
